#!/usr/bin/env node
/**
 * End-to-end audit pipeline check against the LOCAL LLM STUB (not a live LLM).
 *
 * What is real here:
 *   - the Fricta backend (apps/backend/src/index.ts, run with tsx)
 *   - Clerk JWT verification (@hono/clerk-auth → @clerk/backend), in
 *     networkless mode: CLERK_JWT_KEY is a PEM public key generated by this
 *     script, and test session tokens are signed with its private key. No
 *     auth middleware is mocked or bypassed.
 *   - PostgreSQL (DATABASE_URL) and Redis/BullMQ (REDIS_URL)
 *   - the BullMQ worker, Playwright/Chromium browsing a local target site,
 *     screenshots on disk, report generation, visual + UX analysis, exports
 *
 * What is a stub:
 *   - the LLM: AGENT_BASE_URL points at e2e/stub-llm-server.mjs, which
 *     returns scripted replies. Passing here says nothing about real-model
 *     behaviour.
 *
 * Prerequisites: Postgres + Redis running, migrations applied, packages built
 * (`npx turbo run build --filter=@fricta/backend...`).
 *
 * Usage:
 *   DATABASE_URL=... REDIS_URL=... node apps/backend/e2e/run-audit-e2e.mjs [--out results.json]
 * Optional: PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH for a preinstalled Chromium.
 */
import http from 'node:http';
import crypto from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { spawn } from 'node:child_process';
import { fileURLToPath } from 'node:url';

const here = path.dirname(fileURLToPath(import.meta.url));
const backendDir = path.resolve(here, '..');
const repoRoot = path.resolve(backendDir, '../..');
const outArg = process.argv.indexOf('--out');
const outFile = outArg > -1 ? process.argv[outArg + 1] : null;
// --keep-alive <state.json>: after the checks, leave the backend, stub and
// target site running and write {api, token, ids} there (for screenshotting
// pages against real data). Stop with Ctrl-C / SIGTERM. The token is an
// ephemeral test JWT for this run's throwaway keypair; keep the file out of git.
const keepArg = process.argv.indexOf('--keep-alive');
const keepAliveFile = keepArg > -1 ? process.argv[keepArg + 1] : null;

const API_PORT = Number(process.env.E2E_API_PORT || 3101);
const STUB_PORT = Number(process.env.E2E_STUB_PORT || 4010);
const SITE_PORT = Number(process.env.E2E_SITE_PORT || 4020);
const API = `http://127.0.0.1:${API_PORT}`;

const results = [];
function record(step, ok, detail = '') {
  results.push({ step, ok, detail });
  console.log(`${ok ? 'PASS' : 'FAIL'}  ${step}${detail ? ` — ${detail}` : ''}`);
}
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ─── Test Clerk keypair + token minting (networkless verification) ──────────
const { publicKey, privateKey } = crypto.generateKeyPairSync('rsa', { modulusLength: 2048 });
const jwtPublicPem = publicKey.export({ type: 'spki', format: 'pem' }).toString();
const b64url = (b) => Buffer.from(b).toString('base64url');
function mintSessionToken(userId) {
  const now = Math.floor(Date.now() / 1000);
  const header = { alg: 'RS256', typ: 'JWT', kid: 'ins_e2e_local' };
  const payload = {
    sub: userId, sid: `sess_${userId}`, iss: 'https://fricta-e2e.clerk.accounts.dev',
    iat: now - 5, nbf: now - 5, exp: now + 3600, v: 2,
  };
  const input = `${b64url(JSON.stringify(header))}.${b64url(JSON.stringify(payload))}`;
  const sig = crypto.sign('RSA-SHA256', Buffer.from(input), privateKey);
  return `${input}.${b64url(sig)}`;
}
// Publishable keys are public identifiers: "pk_test_" + base64("<frontend-api>$").
const fakePublishableKey = `pk_test_${Buffer.from('fricta-e2e.clerk.accounts.dev$').toString('base64')}`;

const OWNER = 'user_e2e_owner';
const INTRUDER = 'user_e2e_intruder';
const ownerToken = mintSessionToken(OWNER);
const intruderToken = mintSessionToken(INTRUDER);

async function api(method, p, { token = ownerToken, body, raw = false } = {}) {
  const res = await fetch(`${API}${p}`, {
    method,
    headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body ? { 'Content-Type': 'application/json' } : {}) },
    body: body ? JSON.stringify(body) : undefined,
  });
  if (raw) return res;
  const text = await res.text();
  let json = null;
  try { json = JSON.parse(text); } catch {}
  return { status: res.status, json, text, headers: res.headers };
}

// ─── Local target website (what the agent audits) ──────────────────────────
const page = (title, body) => `<!doctype html><html><head><meta charset="utf-8"><title>${title}</title>
<style>body{font-family:sans-serif;margin:0}nav a{margin-right:16px}header{padding:16px;background:#eef}
.hero{padding:48px 16px}.overlap{position:relative;height:120px}.overlap button{position:absolute;top:0;left:0}
.overlap span{position:absolute;top:4px;left:8px}</style></head><body>${body}</body></html>`;
const site = http.createServer((req, res) => {
  const p = (req.url || '/').split('?')[0];
  // /alpha and /beta are two distinct sites used to detect cross-session
  // mixing when audits run concurrently; their pricing pages carry the prefix.
  const tenant = (p.match(/^\/(alpha|beta)(\/|$)/) || [])[1] || '';
  const prefix = tenant ? `/${tenant}` : '';
  const html = p.startsWith('/no-exit')
    // No links, buttons or inputs at all: the stub declares dead_end.
    ? page('Acme — No exit', `<main class="hero"><h1>Nothing to do here</h1><p>${'Static text only. '.repeat(60)}</p></main>`)
    : p.startsWith('/dead-end')
    ? page('Acme — Nowhere', `<header><nav><a href="/dead-end">Home</a></nav></header><main class="hero"><h1>Welcome</h1><p>${'No way forward. '.repeat(120)}</p></main>`)
    : p.includes('/pricing')
    ? page(`Acme${tenant ? ' ' + tenant : ''} — Pricing`, `<header><nav><a href="${prefix || '/'}">Home</a></nav></header><main class="hero"><h1>Pricing ${tenant}</h1><p>Starter: free. Team: contact us.</p><button>Start free</button></main>`)
    : page(`Acme${tenant ? ' ' + tenant : ''} — Home`, `<header><nav><a href="${prefix || '/'}">Home</a><a href="${prefix}/pricing">Pricing</a><a href="${prefix}/about">About</a></nav></header>
<main class="hero"><h1>Acme ${tenant || ''} ships faster</h1><p>${'Long marketing copy. '.repeat(80)}</p>
<div class="overlap"><button>Get started</button><span>Overlapping label</span></div><input placeholder="Email address"></main>`);
  res.writeHead(200, { 'Content-Type': 'text/html' });
  res.end(html);
});

// ─── Process management ────────────────────────────────────────────────────
const children = [];
let backendEnv = null;
function startChild(name, cmd, args, opts) {
  const child = spawn(cmd, args, { ...opts, stdio: ['ignore', 'pipe', 'pipe'] });
  const logPath = path.join(opts.logDir, `${name}.log`);
  const log = fs.createWriteStream(logPath);
  child.stdout.pipe(log); child.stderr.pipe(log);
  children.push(child);
  return { child, logPath };
}
async function waitFor(fn, timeoutMs, intervalMs = 500) {
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    try { const v = await fn(); if (v) return v; } catch {}
    await sleep(intervalMs);
  }
  return null;
}
function cleanup() { for (const c of children) { try { c.kill('SIGTERM'); } catch {} } site.close(); }
process.on('exit', cleanup);

// ─── BullMQ queue depth (direct Redis read) ───────────────────────────────
async function queueDepth() {
  const { Redis } = await import(path.join(repoRoot, 'node_modules/ioredis/built/index.js'));
  const r = new Redis(process.env.REDIS_URL || 'redis://localhost:6379');
  try {
    const q = 'bull:workflow-execution';
    const [wait, active, delayed] = await Promise.all([r.llen(`${q}:wait`), r.llen(`${q}:active`), r.zcard(`${q}:delayed`)]);
    return { wait, active, delayed };
  } finally { r.disconnect(); }
}

// ─── SSE helper ────────────────────────────────────────────────────────────
async function readSse(p, token, ms) {
  const controller = new AbortController();
  const events = [];
  const timer = setTimeout(() => controller.abort(), ms);
  try {
    const res = await fetch(`${API}${p}${p.includes('?') ? '&' : '?'}token=${encodeURIComponent(token)}`, { signal: controller.signal });
    if (!res.ok) return { status: res.status, events };
    const reader = res.body.getReader();
    const dec = new TextDecoder();
    let buf = '';
    for (;;) {
      const { value, done } = await reader.read();
      if (done) break;
      buf += dec.decode(value, { stream: true });
      let idx;
      while ((idx = buf.indexOf('\n\n')) > -1) {
        const chunk = buf.slice(0, idx); buf = buf.slice(idx + 2);
        const ev = (chunk.match(/^event: ?(.*)$/m) || [])[1];
        if (ev) events.push(ev);
        if (ev === 'system.hydrated') { controller.abort(); }
      }
    }
    return { status: res.status, events };
  } catch {
    return { status: 200, events };
  } finally { clearTimeout(timer); }
}

// ─── Main ──────────────────────────────────────────────────────────────────
async function main() {
  const logDir = fs.mkdtempSync(path.join(process.env.TMPDIR || '/tmp', 'fricta-e2e-'));
  console.log(`[e2e] logs: ${logDir}`);
  console.log('[e2e] LLM: local STUB (not a live LLM)');

  await new Promise((r) => site.listen(SITE_PORT, '127.0.0.1', r));
  const stub = startChild('stub-llm', process.execPath, [path.join(here, 'stub-llm-server.mjs'), String(STUB_PORT)], { logDir, cwd: here, env: process.env });
  const stubUp = await waitFor(async () => (await fetch(`http://127.0.0.1:${STUB_PORT}/__stub/stats`)).ok, 10_000);
  record('stub LLM server up', !!stubUp, stub.logPath);

  const env = {
    ...process.env,
    NODE_ENV: 'development',
    PORT: String(API_PORT),
    FRONTEND_URL: 'http://localhost:5173',
    CLERK_SECRET_KEY: 'sk_test_e2e_local_not_a_real_key',
    CLERK_PUBLISHABLE_KEY: fakePublishableKey,
    CLERK_JWT_KEY: jwtPublicPem,
    AGENT_BASE_URL: `http://127.0.0.1:${STUB_PORT}/v1`,
    AGENT_API_KEY: '',
    OPENROUTER_API_KEY: '',
    AGENT_MODEL: process.env.E2E_AGENT_MODEL || 'google/gemma-4-31b-it:free',
    AGENT_VISION_MODEL: process.env.E2E_VISION_MODEL || 'google/gemma-4-31b-it:free',
    ALLOW_PAID_MODELS: '',
    WORKER_CONCURRENCY: '1',
  };
  backendEnv = env;
  const backend = startChild('backend', path.join(repoRoot, 'node_modules/.bin/tsx'), ['src/index.ts'], { logDir, cwd: backendDir, env });
  const healthy = await waitFor(async () => (await fetch(`${API}/health`)).ok, 90_000, 1000);
  record('backend boots (env validation, DB, Redis, migrations)', !!healthy, backend.logPath);
  if (!healthy) return finish();

  // Auth
  const unauth = await api('GET', '/api/projects', { token: null });
  record('unauthenticated request rejected', unauth.status === 401, `HTTP ${unauth.status}`);
  const forged = await api('GET', '/api/projects', { token: ownerToken.slice(0, -4) + 'AAAA' });
  record('token with bad signature rejected', forged.status === 401, `HTTP ${forged.status}`);

  // Project
  const created = await api('POST', '/api/projects', { body: { projectName: 'E2E stub audit', websiteUrl: `http://127.0.0.1:${SITE_PORT}/` } });
  const projectId = created.json?.project?.id;
  record('create project', created.status < 300 && !!projectId, `HTTP ${created.status}`);
  if (!projectId) return finish();

  // Launch
  const launch = await api('POST', '/api/agent/workflow/run', {
    body: { projectId, url: `http://127.0.0.1:${SITE_PORT}/`, goal: 'Find the pricing page', persona: 'Tech-Savvy User' },
  });
  const sessionId = launch.json?.sessionId;
  record('launch audit (POST /api/agent/workflow/run)', launch.status === 200 && !!sessionId, `HTTP ${launch.status} model=${launch.json?.model}`);
  if (!sessionId) return finish();

  const foreign = await api('GET', `/api/agent/workflow/${sessionId}/status`, { token: intruderToken });
  record('other user cannot read the audit', foreign.status === 403, `HTTP ${foreign.status}`);

  // Worker run + status
  const statuses = new Set();
  const terminal = await waitFor(async () => {
    const s = await api('GET', `/api/agent/workflow/${sessionId}/status`);
    const st = s.json?.session?.status;
    if (st) statuses.add(st);
    return ['COMPLETED', 'FAILED', 'TIMEOUT', 'LOOP_DETECTED'].includes(st) ? s.json.session : null;
  }, 180_000, 1000);
  record('worker runs audit to a terminal status', !!terminal, `seen=${[...statuses].join('→')} final=${terminal?.status} steps=${terminal?.stepCount}`);
  record('audit completes (goal reached)', terminal?.status === 'COMPLETED', `final=${terminal?.status}`);

  const thoughts = await api('GET', `/api/agent/workflow/${sessionId}/thoughts`);
  const actions = await api('GET', `/api/agent/workflow/${sessionId}/actions`);
  const actList = actions.json?.actions || [];
  record('thoughts persisted', (thoughts.json?.thoughts || []).length > 0, `${(thoughts.json?.thoughts || []).length} thoughts`);
  record('actions persisted', actList.length > 0, actList.map((a) => `${a.action}:${a.target}:${a.status}`).join(', '));
  record('agent clicked through to pricing', actList.some((a) => a.action === 'click' && a.target === 'Pricing' && a.status === 'success'));

  const list = await api('GET', `/api/workflows?projectId=${projectId}`);
  record('audit listed under project', (list.json?.sessions || []).some((s) => s.id === sessionId), `HTTP ${list.status}`);

  // SSE
  for (const stream of ['replay', 'timeline', 'orchestration']) {
    const sse = await readSse(`/api/realtime/${stream}/${sessionId}`, ownerToken, 8000);
    record(`SSE /api/realtime/${stream} connects + hydrates`, sse.status === 200 && sse.events.includes('system.connected') && sse.events.includes('system.hydrated'), `HTTP ${sse.status} events=${sse.events.join(',')}`);
  }
  const sseForeign = await readSse(`/api/realtime/replay/${sessionId}`, intruderToken, 4000);
  record('SSE rejects other user', sseForeign.status === 403, `HTTP ${sseForeign.status}`);

  // Report (auto-generated by the worker 'completed' listener)
  const report = await waitFor(async () => {
    const r = await api('GET', `/api/reports/${sessionId}`);
    return r.status === 200 && r.json ? r : null;
  }, 60_000, 1500);
  record('report generated + readable', !!report, report ? `keys=${Object.keys(report.json).slice(0, 8).join(',')}` : 'no report');
  const reports = await api('GET', '/api/reports');
  record('report in /api/reports list', (reports.json?.reports || []).some((r) => r.sessionId === sessionId), `HTTP ${reports.status}`);
  const exec = await api('GET', `/api/reports/${sessionId}/executive`);
  record('executive summary', exec.status === 200, `HTTP ${exec.status}`);
  const timeline = await api('GET', `/api/reports/${sessionId}/timeline`);
  record('report timeline', timeline.status === 200, `HTTP ${timeline.status}`);

  // Exports
  const exp = await api('GET', `/api/reports/${sessionId}/export`);
  record('JSON export', exp.status === 200 && !!exp.json, `HTTP ${exp.status}`);
  const pdf = await api('GET', `/api/reports/${sessionId}/export/pdf`, { raw: true });
  const pdfBuf = Buffer.from(await pdf.arrayBuffer());
  const pdfType = pdf.headers.get('content-type') || '';
  record('PDF export', pdf.status === 200 && (pdfBuf.subarray(0, 5).toString() === '%PDF-' || pdfType.includes('json')), `HTTP ${pdf.status} type=${pdfType} bytes=${pdfBuf.length} head=${JSON.stringify(pdfBuf.subarray(0, 5).toString())}`);

  // Replay
  const replay = await api('GET', `/api/workflows/${sessionId}/visual-replay`);
  const frames = replay.json?.timeline || replay.json?.events || replay.json?.frames || [];
  record('visual replay timeline', replay.status === 200, `HTTP ${replay.status} keys=${Object.keys(replay.json || {}).join(',')} items=${Array.isArray(frames) ? frames.length : '?'}`);
  const shotPath = replay.json?.screenshots?.[0]?.filePath;
  if (shotPath) {
    const anon = await api('GET', `/api/workflows/screenshots/raw/${shotPath}`, { token: null, raw: true });
    const own = await api('GET', `/api/workflows/screenshots/raw/${shotPath}`, { raw: true });
    const bytes = (await own.arrayBuffer()).byteLength;
    record('replay screenshot served only with auth', anon.status === 401 && own.status === 200 && bytes > 1000,
      `anon=${anon.status} owner=${own.status} type=${own.headers.get('content-type')} bytes=${bytes}`);
  } else record('replay screenshot served only with auth', false, 'no screenshot in replay');
  const vt = await api('GET', `/api/workflows/${sessionId}/visual-timeline`);
  record('screenshot timeline events', (vt.json?.timelineEvents || []).length > 0, `${(vt.json?.timelineEvents || []).length} events`);

  // Findings
  const visual = await api('POST', `/api/visual/analyze/${sessionId}`, { body: { forceAIVision: true } });
  record('visual analysis (vision via stub)', visual.status === 200, `HTTP ${visual.status} aiUsed=${visual.json?.aiAnalysisUsed} findings=${visual.json?.findings?.length}`);
  const vf = await api('GET', `/api/visual/findings/${sessionId}`);
  record('visual findings persisted', (vf.json?.findings || []).length > 0, `${(vf.json?.findings || []).length} findings`);
  const vs = await api('GET', `/api/visual/scores/${sessionId}`);
  record('visual score persisted', vs.status === 200 && !!vs.json?.score, `HTTP ${vs.status}`);
  const ux = await api('POST', `/api/ux/analyze/${sessionId}`, { body: {} });
  record('UX analysis', ux.status === 200, `HTTP ${ux.status}`);
  const uxf = await api('GET', `/api/ux/findings/${sessionId}`);
  record('UX findings readable', uxf.status === 200, `HTTP ${uxf.status} count=${(uxf.json?.findings || []).length}`);
  const rec = await api('GET', `/api/ux/recommendations/${sessionId}`);
  record('UX recommendations readable', rec.status === 200, `HTTP ${rec.status}`);

  // Multi-agent orchestration (report "agents" tab) + shared memory
  const orch = await api('POST', `/api/orchestrator/start/${sessionId}`, { body: {} });
  record('orchestrator run', orch.status === 200, `HTTP ${orch.status}`);
  const agentFindings = await api('GET', `/api/agents/${sessionId}/findings`);
  record('agent findings readable', agentFindings.status === 200, `HTTP ${agentFindings.status} count=${(agentFindings.json?.findings || []).length}`);
  const mem = await api('GET', `/api/memory/${sessionId}`);
  record('shared memory readable', mem.status === 200, `HTTP ${mem.status}`);

  const hist = await api('POST', `/api/historical/analyze/${projectId}`, { body: {} });
  record('historical analysis (project-scoped POST)', hist.status === 200, `HTTP ${hist.status} ${hist.json?.error || ''}`);
  const histForeign = await api('POST', `/api/historical/analyze/${projectId}`, { token: intruderToken, body: {} });
  record('historical analysis rejects other user', histForeign.status === 403, `HTTP ${histForeign.status}`);

  // Cross-user isolation on every session-scoped read used by the report UI.
  const isolation = [
    ['GET', `/api/reports/${sessionId}`], ['GET', `/api/reports/${sessionId}/export`],
    ['GET', `/api/reports/${sessionId}/export/pdf`], ['GET', `/api/workflows/${sessionId}/visual-replay`],
    ['GET', `/api/visual/findings/${sessionId}`], ['GET', `/api/ux/findings/${sessionId}`],
    ['GET', `/api/ux/cognitive/${sessionId}`], ['GET', `/api/ux/recommendations/${sessionId}`],
    ['POST', `/api/ux/analyze/${sessionId}`], ['GET', `/api/agents/${sessionId}/findings`],
    ['GET', `/api/orchestrator/${sessionId}`], ['GET', `/api/memory/${sessionId}`],
    ['GET', `/api/memory/${sessionId}/insights`],
  ];
  const leaks = [];
  for (const [m, p] of isolation) {
    const r = await api(m, p, { token: intruderToken, body: m === 'POST' ? {} : undefined });
    if (r.status !== 403 && r.status !== 404) leaks.push(`${m} ${p.replace(sessionId, ':id')} → ${r.status}`);
  }
  record('other user blocked on all session-scoped routes', leaks.length === 0, leaks.join('; ') || `${isolation.length} routes checked`);

  // Second scenario: the goal is unreachable, so the run must end without
  // success and still produce a diagnostic report with friction findings.
  const dead = await api('POST', '/api/agent/workflow/run', {
    body: { projectId, url: `http://127.0.0.1:${SITE_PORT}/dead-end`, goal: 'Find the pricing page', persona: 'Tech-Savvy User' },
  });
  const deadId = dead.json?.sessionId;
  const deadEnd = deadId && await waitFor(async () => {
    const st = (await api('GET', `/api/agent/workflow/${deadId}/status`)).json?.session;
    return st && ['COMPLETED', 'FAILED', 'TIMEOUT', 'LOOP_DETECTED'].includes(st.status) ? st : null;
  }, 180_000, 1000);
  record('dead-end audit ends unsuccessfully', !!deadEnd && deadEnd.status !== 'COMPLETED', `final=${deadEnd?.status} steps=${deadEnd?.stepCount}`);
  const deadReport = deadId && await waitFor(async () => {
    const r = await api('GET', `/api/reports/${deadId}`);
    return r.status === 200 ? r : null;
  }, 60_000, 1500);
  record('dead-end audit still gets a diagnostic report', !!deadReport);
  if (deadId) {
    await api('POST', `/api/ux/analyze/${deadId}`, { body: {} });
    const df = await api('GET', `/api/ux/findings/${deadId}`);
    record('dead-end audit produces UX friction findings', (df.json?.findings || []).length > 0, `count=${(df.json?.findings || []).length} ${(df.json?.findings || []).slice(0, 3).map((f) => f.title).join(' | ')}`);
  }

  // ── Score: one source of truth across report, grade, exports, list ──────
  const gradeOf = (n) => (n >= 90 ? 'A' : n >= 80 ? 'B' : n >= 70 ? 'C' : n >= 60 ? 'D' : 'F');
  async function scoreView(id) {
    // Sequential on purpose: the list is read after the report is compiled.
    const rep = await api('GET', `/api/reports/${id}`);
    const ex = await api('GET', `/api/reports/${id}/executive`);
    const xp = await api('GET', `/api/reports/${id}/export`);
    const list = await api('GET', '/api/reports');
    return {
      report: rep.json?.scores?.overallScore, basis: rep.json?.scores?.basis,
      exec: ex.json?.overallScore, grade: ex.json?.overallUXGrade,
      markdown: xp.json?.markdown || '', pm: xp.json?.textSheet || '',
      listed: (list.json?.reports || []).find((r) => r.sessionId === id)?.score,
      visualFindings: (rep.json?.visualFindings || []).length, uxFindings: (rep.json?.uxFindings || []).length,
    };
  }
  const listAfterAnalysis = ((await api('GET', '/api/reports')).json?.reports || []).find((r) => r.sessionId === sessionId)?.score;
  const happy = await scoreView(sessionId);
  record('reports list is refreshed by analysis (not only when the report is opened)', listAfterAnalysis === happy.report,
    `list-before-open=${listAfterAnalysis} report=${happy.report}`);
  record('score: report, executive grade and reports list agree (happy path)',
    happy.report === happy.exec && happy.listed === happy.report && happy.grade === gradeOf(happy.report),
    `report=${happy.report} exec=${happy.exec} list=${happy.listed} grade=${happy.grade} basis=${JSON.stringify(happy.basis)}`);
  record('score: findings lower the happy-path score below 100',
    happy.visualFindings + happy.uxFindings === 0 || happy.report < 100,
    `visualFindings=${happy.visualFindings} uxFindings=${happy.uxFindings} score=${happy.report}`);
  record('Markdown export carries the same score + grade',
    happy.markdown.includes(`**${happy.exec}/100** | **Grade: ${happy.grade}**`) && happy.markdown.includes('Find the pricing page'),
    `${happy.markdown.length} chars`);
  record('PM summary export carries the same score + grade',
    happy.pm.includes(`Overall Score: ${happy.exec}/100 (Grade: ${happy.grade})`), `${happy.pm.length} chars`);
  if (deadId) {
    const dead = await scoreView(deadId);
    record('score: dead-end audit (goal not reached) is graded F, not A 100/100',
      dead.grade === 'F' && dead.report <= 55 && dead.basis?.goalReached === false && dead.report === dead.exec && dead.listed === dead.report,
      `report=${dead.report} exec=${dead.exec} list=${dead.listed} grade=${dead.grade} visualFindings=${dead.visualFindings} basis=${JSON.stringify(dead.basis)}`);
    record('dead-end audit has visual findings at report time (auto-analysis on completion)', dead.visualFindings > 0, `visualFindings=${dead.visualFindings}`);
  }

  // ── Executive report → exports ─────────────────────────────────────────────
  const execRep = await api('POST', '/api/reports/executive', { body: { projectId, title: 'E2E executive report' } });
  const execId = execRep.json?.report?.id;
  record('create executive report', execRep.status === 200 && !!execId, `HTTP ${execRep.status} ${execRep.json?.error || ''}`);
  if (execId) {
    const pdfExp = await api('POST', '/api/reports/exports', { body: { reportId: execId, format: 'PDF' } });
    const pdfExportId = pdfExp.json?.export?.id;
    record('POST /api/reports/exports (PDF) queues an export', pdfExp.status === 200 && pdfExp.json?.export?.status === 'PENDING', `HTTP ${pdfExp.status}`);
    const done = await waitFor(async () => {
      const l = await api('GET', `/api/reports/exports?reportId=${execId}`);
      const e = (l.json?.exports || []).find((x) => x.id === pdfExportId);
      return e && ['COMPLETED', 'FAILED'].includes(e.status) ? { l, e } : null;
    }, 60_000, 1000);
    record('GET /api/reports/exports lists it and it completes', done?.e?.status === 'COMPLETED', `list HTTP ${done?.l?.status} status=${done?.e?.status}`);
    const dl = await api('GET', `/api/reports/exports/${pdfExportId}/download`, { raw: true });
    const dlBuf = Buffer.from(await dl.arrayBuffer());
    record('GET /api/reports/exports/:id/download returns the PDF', dl.status === 200 && dlBuf.subarray(0, 5).toString() === '%PDF-', `HTTP ${dl.status} bytes=${dlBuf.length}`);
    const dlForeign = await api('GET', `/api/reports/exports/${pdfExportId}/download`, { token: intruderToken });
    const listForeign = await api('GET', `/api/reports/exports?reportId=${execId}`, { token: intruderToken });
    const createForeign = await api('POST', '/api/reports/exports', { token: intruderToken, body: { reportId: execId, format: 'PDF' } });
    record('exports deny other users (list, create, download)', [dlForeign.status, listForeign.status, createForeign.status].every((x) => x === 403),
      `download=${dlForeign.status} list=${listForeign.status} create=${createForeign.status}`);
    const snap = await api('POST', '/api/reports/exports', { body: { reportId: execId, format: 'SNAPSHOT' } });
    const snapDone = await waitFor(async () => {
      const e = ((await api('GET', `/api/reports/exports?reportId=${execId}`)).json?.exports || []).find((x) => x.id === snap.json?.export?.id);
      return e && e.status !== 'PENDING' && e.status !== 'GENERATING' ? e : null;
    }, 30_000, 1000);
    record('unimplemented export formats fail honestly (no fake success)', snapDone?.status === 'FAILED', `status=${snapDone?.status} reason=${snapDone?.metadata?.reason}`);

    // ── Sharing ──────────────────────────────────────────────────────────────
    const share = await api('POST', '/api/reports/sharing', { body: { reportId: execId, expiresHours: 1 } });
    const token = share.json?.share?.token;
    record('create share link', share.status === 200 && !!token, `HTTP ${share.status}`);
    const listed = await api('GET', `/api/reports/sharing?reportId=${execId}`);
    record('GET /api/reports/sharing lists it', (listed.json?.shares || []).some((x) => x.token === token), `HTTP ${listed.status}`);
    const anon = await api('GET', `/api/shared/${token}`, { token: null });
    const anonKeys = Object.keys(anon.json?.report || {});
    record('anonymous visitor opens the share link', anon.status === 200 && anon.json?.report?.id === execId, `HTTP ${anon.status}`);
    record('public share response exposes no creator/recipient data',
      !JSON.stringify(anon.json || {}).includes(OWNER) && !('createdById' in (anon.json?.report || {})) && !('share' in (anon.json || {})),
      `keys=${anonKeys.join(',')}`);
    const bogus = await api('GET', `/api/shared/${'0'.repeat(48)}`, { token: null });
    record('unknown share token rejected', bogus.status === 403, `HTTP ${bogus.status}`);
    const shareForeign = await api('POST', '/api/reports/sharing', { token: intruderToken, body: { reportId: execId } });
    const listShareForeign = await api('GET', `/api/reports/sharing?reportId=${execId}`, { token: intruderToken });
    const revokeForeign = await api('POST', '/api/reports/sharing/revoke', { token: intruderToken, body: { shareId: share.json?.share?.id } });
    record('sharing denies other users (create, list, revoke)', [shareForeign.status, listShareForeign.status, revokeForeign.status].every((x) => x === 403),
      `create=${shareForeign.status} list=${listShareForeign.status} revoke=${revokeForeign.status}`);
    const stillOpen = await api('GET', `/api/shared/${token}`, { token: null });
    record('foreign revoke attempt did not revoke', stillOpen.status === 200, `HTTP ${stillOpen.status}`);
    const revoke = await api('POST', '/api/reports/sharing/revoke', { body: { shareId: share.json?.share?.id } });
    const afterRevoke = await api('GET', `/api/shared/${token}`, { token: null });
    record('revoked token stops working', revoke.status === 200 && afterRevoke.status === 403, `revoke=${revoke.status} open=${afterRevoke.status}`);
    const short = await api('POST', '/api/reports/sharing', { body: { reportId: execId, expiresHours: 1 / 3600 } }); // ~1 s
    await sleep(2500);
    const expired = await api('GET', `/api/shared/${short.json?.share?.token}`, { token: null });
    record('expired token rejected', short.status === 200 && expired.status === 403, `create=${short.status} open=${expired.status}`);
    const once = await api('POST', '/api/reports/sharing', { body: { reportId: execId, maxUses: 1 } });
    const use1 = await api('GET', `/api/shared/${once.json?.share?.token}`, { token: null });
    const use2 = await api('GET', `/api/shared/${once.json?.share?.token}`, { token: null });
    record('max-uses limit enforced', use1.status === 200 && use2.status === 403, `first=${use1.status} second=${use2.status}`);
  }

  // ── dead_end terminal path → LOOP_DETECTED ─────────────────────────────────
  const noExit = await api('POST', '/api/agent/workflow/run', {
    body: { projectId, url: `http://127.0.0.1:${SITE_PORT}/no-exit`, goal: 'Find the pricing page', persona: 'Tech-Savvy User' },
  });
  const noExitId = noExit.json?.sessionId;
  const noExitEnd = noExitId && await waitFor(async () => {
    const st = (await api('GET', `/api/agent/workflow/${noExitId}/status`)).json?.session;
    return st && ['COMPLETED', 'FAILED', 'TIMEOUT', 'LOOP_DETECTED'].includes(st.status) ? st : null;
  }, 120_000, 1000);
  const noExitActs = noExitId ? ((await api('GET', `/api/agent/workflow/${noExitId}/actions`)).json?.actions || []) : [];
  record('dead_end terminal signal ends the run as LOOP_DETECTED',
    noExitEnd?.status === 'LOOP_DETECTED' && noExitActs.some((a) => a.action === 'wait' && a.target === 'dead_end'),
    `final=${noExitEnd?.status} actions=${noExitActs.map((a) => `${a.action}:${a.target}`).join(',')}`);
  if (noExitId) {
    const ne = await waitFor(async () => { const v = await scoreView(noExitId); return v.exec !== undefined ? v : null; }, 60_000, 1500);
    record('LOOP_DETECTED audit gets a report graded F', ne?.grade === 'F', `score=${ne?.report} grade=${ne?.grade}`);
  }

  // ── Concurrency: two audits at once, two worker processes ──────────────────
  const API2_PORT = API_PORT + 1;
  const backend2 = startChild('backend-2', path.join(repoRoot, 'node_modules/.bin/tsx'), ['src/index.ts'],
    { logDir, cwd: backendDir, env: { ...backendEnv, PORT: String(API2_PORT) } });
  const healthy2 = await waitFor(async () => (await fetch(`http://127.0.0.1:${API2_PORT}/health`)).ok, 90_000, 1000);
  record('second backend/worker process boots on the same DB + Redis', !!healthy2, backend2.logPath);
  const [ra, rb] = await Promise.all(['alpha', 'beta'].map((t) => api('POST', '/api/agent/workflow/run', {
    body: { projectId, url: `http://127.0.0.1:${SITE_PORT}/${t}`, goal: 'Find the pricing page', persona: 'Tech-Savvy User' },
  })));
  const conc = { alpha: ra.json?.sessionId, beta: rb.json?.sessionId };
  record('two audits launched concurrently', !!conc.alpha && !!conc.beta && conc.alpha !== conc.beta, `alpha=${conc.alpha} beta=${conc.beta}`);
  const ends = await Promise.all(Object.values(conc).map((id) => waitFor(async () => {
    const st = (await api('GET', `/api/agent/workflow/${id}/status`)).json?.session;
    return st && ['COMPLETED', 'FAILED', 'TIMEOUT', 'LOOP_DETECTED'].includes(st.status) ? st : null;
  }, 180_000, 1000)));
  record('both concurrent audits complete (no stuck jobs)', ends.every((e) => e?.status === 'COMPLETED'), ends.map((e) => `${e?.status}/${e?.stepCount}`).join(' '));
  for (const [tenant, id] of Object.entries(conc)) {
    const other = tenant === 'alpha' ? 'beta' : 'alpha';
    const rp = (await api('GET', `/api/workflows/${id}/visual-replay`)).json || {};
    const urls = (rp.screenshots || []).map((x) => x.pageUrl);
    const acts = (await api('GET', `/api/agent/workflow/${id}/actions`)).json?.actions || [];
    record(`no cross-session mixing (${tenant})`,
      urls.length > 0 && urls.every((u) => u.includes(`/${tenant}`) && !u.includes(`/${other}`)) && acts.length === 3 && new Set(acts.map((a) => a.stepNumber)).size === acts.length,
      `screenshots=${urls.map((u) => new URL(u).pathname).join(',')} actions=${acts.map((a) => `${a.stepNumber}:${a.action}`).join(',')}`);
  }
  await sleep(4000); // let both completion listeners finish
  const reportCounts = {};
  for (const id of Object.values(conc)) {
    reportCounts[id] = ((await api('GET', '/api/reports')).json?.reports || []).filter((r) => r.sessionId === id).length;
  }
  record('exactly one report per concurrent audit (no duplicates)', Object.values(reportCounts).every((n) => n === 1), JSON.stringify(reportCounts));
  const logs = [backend.logPath, backend2.logPath].map((f) => fs.readFileSync(f, 'utf8'));
  // The 'completed' listener runs only in the process whose worker ran the job.
  const workerOf = Object.fromEntries(Object.entries(conc).map(([t, id]) => [t,
    logs.flatMap((l, i) => Array(l.split(`Job completed. Auto-generating report for session ${id}`).length - 1).fill(`backend-${i + 1}`))]));
  record('each concurrent job processed by exactly one worker', Object.values(workerOf).every((w) => w.length === 1), JSON.stringify(workerOf));
  const qWait = await queueDepth();
  record('queue drained (no waiting/active/delayed jobs left)', qWait.wait === 0 && qWait.active === 0 && qWait.delayed === 0, JSON.stringify(qWait));

  // ── Rate limits: insufficient evidence + incomplete visual coverage ───────
  const stubMode = async (m) => (await fetch(`http://127.0.0.1:${STUB_PORT}/__stub/mode`, { method: 'POST', body: JSON.stringify(m) })).json();
  const stubStats = async () => (await fetch(`http://127.0.0.1:${STUB_PORT}/__stub/stats`)).json();

  // (a) Every planner call is rate-limited → the run fails with no actions.
  const before429 = (await stubStats()).planner429;
  await stubMode({ planner: '429' });
  const ie = await api('POST', '/api/agent/workflow/run', {
    body: { projectId, url: `http://127.0.0.1:${SITE_PORT}/`, goal: 'Find the pricing page', persona: 'Tech-Savvy User' },
  });
  const ieId = ie.json?.sessionId;
  const ieEnd = ieId && await waitFor(async () => {
    const st = (await api('GET', `/api/agent/workflow/${ieId}/status`)).json?.session;
    return st && ['COMPLETED', 'FAILED', 'TIMEOUT', 'LOOP_DETECTED'].includes(st.status) ? st : null;
  }, 180_000, 1000);
  await stubMode({ planner: 'ok' });
  const ieActs = ieId ? ((await api('GET', `/api/agent/workflow/${ieId}/actions`)).json?.actions || []) : [];
  const planner429 = (await stubStats()).planner429 - before429;
  record('planner 429s are retried 5× per call, then the run fails with 0 actions',
    ieEnd?.status === 'FAILED' && ieActs.length === 0 && planner429 > 0 && planner429 % 5 === 0,
    `final=${ieEnd?.status} actions=${ieActs.length} stub429=${planner429}`);
  if (ieId) {
    const ieRep = await waitFor(async () => { const r = await api('GET', `/api/reports/${ieId}`); return r.status === 200 ? r : null; }, 60_000, 1500);
    const ieExec = await api('GET', `/api/reports/${ieId}/executive`);
    const ieExp = await api('GET', `/api/reports/${ieId}/export`);
    const ieList = ((await api('GET', '/api/reports')).json?.reports || []).find((r) => r.sessionId === ieId);
    const iePdf = await api('GET', `/api/reports/${ieId}/export/pdf`, { raw: true });
    const iePdfHead = Buffer.from(await iePdf.arrayBuffer()).subarray(0, 5).toString();
    record('0-action FAILED audit: no numeric score anywhere (report, grade, list)',
      ieRep?.json?.scores?.overallScore === null && ieRep?.json?.evidence?.status === 'insufficient'
        && ieExec.json?.overallUXGrade === 'N/A' && ieExec.json?.overallScore === null && ieList && ieList.score === null,
      `report=${ieRep?.json?.scores?.overallScore} evidence=${ieRep?.json?.evidence?.status} grade=${ieExec.json?.overallUXGrade} list=${ieList?.score}`);
    record('0-action FAILED audit: exports say "not scored", PDF still renders',
      (ieExp.json?.markdown || '').includes('Not scored: insufficient evidence') && (ieExp.json?.textSheet || '').includes('NOT SCORED')
        && !/null\/100/.test(ieExp.json?.markdown || '') && iePdf.status === 200 && iePdfHead === '%PDF-',
      `pdf=${iePdf.status} ${JSON.stringify(iePdfHead)}`);
  }

  // (b) Vision rate-limited / empty → coverage reported as incomplete.
  async function visionRun(m) {
    const b = await stubStats();
    await stubMode({ vision: m });
    const an = await api('POST', `/api/visual/analyze/${sessionId}`, { body: { forceAIVision: true } });
    await stubMode({ vision: 'ok' });
    const a = await stubStats();
    const rep = await api('GET', `/api/reports/${sessionId}`);
    const ex = await api('GET', `/api/reports/${sessionId}/executive`);
    const xp = await api('GET', `/api/reports/${sessionId}/export`);
    return { an, rep, ex, xp, d429: a.vision429 - b.vision429, dEmpty: a.visionEmpty - b.visionEmpty };
  }
  const v429 = await visionRun('429');
  const cov429 = v429.rep.json?.visualCoverage;
  const unavailable = (v429.rep.json?.visualFindings || []).filter((f) => f.findingType === 'vision_unavailable');
  record('vision 429s are retried 5× per screenshot, then marked unavailable',
    v429.an.status === 200 && v429.an.json?.aiAnalysisUsed === false && v429.d429 > 0 && v429.d429 % 5 === 0 && unavailable.length > 0,
    `analyze=${v429.an.status} aiUsed=${v429.an.json?.aiAnalysisUsed} stub429=${v429.d429} unavailable=${unavailable.length} reason=${unavailable[0]?.metadata?.reason}`);
  record('vision 429: report says visual coverage incomplete (field, executive, exports)',
    cov429?.complete === false && cov429?.status === 'failed' && !!v429.ex.json?.visualCoverageNote
      && (v429.xp.json?.markdown || '').includes('Visual coverage incomplete') && (v429.xp.json?.textSheet || '').includes('Visual Coverage: INCOMPLETE'),
    `coverage=${JSON.stringify(cov429)}`);
  record('a coverage note does not change the grade into a clean result',
    !(v429.rep.json?.visualFindings || []).some((f) => f.findingType === 'vision_summary'),
    `types=${[...new Set((v429.rep.json?.visualFindings || []).map((f) => f.findingType))].join(',')}`);
  const vEmpty = await visionRun('empty');
  record('vision empty responses are retried, then coverage incomplete',
    vEmpty.dEmpty > 0 && vEmpty.dEmpty % 5 === 0 && vEmpty.rep.json?.visualCoverage?.complete === false,
    `stubEmpty=${vEmpty.dEmpty} coverage=${vEmpty.rep.json?.visualCoverage?.status}`);
  const vOk = await visionRun('ok');
  record('vision recovers: coverage complete again once the model answers',
    vOk.rep.json?.visualCoverage?.complete === true && vOk.rep.json?.visualCoverage?.status === 'full',
    `coverage=${vOk.rep.json?.visualCoverage?.status} succeeded=${vOk.rep.json?.visualCoverage?.visionSucceeded}`);

  const stats = await (await fetch(`http://127.0.0.1:${STUB_PORT}/__stub/stats`)).json();
  record('stub actually served planner + vision calls', stats.planner > 0 && stats.vision > 0, JSON.stringify(stats));

  return finish({ projectId, sessionId, deadEndSessionId: deadId, noExitSessionId: noExitId, insufficientEvidenceSessionId: ieId, concurrent: conc, logDir });
}

function finish(extra = {}) {
  const passed = results.filter((r) => r.ok).length;
  console.log(`\n[e2e] ${passed}/${results.length} checks passed (LLM = local stub, not a live model)`);
  if (outFile) fs.writeFileSync(outFile, JSON.stringify({ llm: 'local-stub (not a live LLM)', at: new Date().toISOString(), ...extra, results }, null, 2));
  if (keepAliveFile && extra.sessionId) {
    fs.writeFileSync(keepAliveFile, JSON.stringify({ api: API, token: ownerToken, ...extra }, null, 2), { mode: 0o600 });
    console.log(`[e2e] keep-alive: backend on ${API}, state in ${keepAliveFile}. Ctrl-C to stop.`);
    const stop = () => { cleanup(); process.exit(0); };
    process.on('SIGINT', stop); process.on('SIGTERM', stop);
    return;
  }
  cleanup();
  process.exit(passed === results.length ? 0 : 1);
}

main().catch((err) => { console.error(err); record('harness crashed', false, err.message); finish(); });
